import{_ as e,o as t,c as s,a2 as i}from"./chunks/framework.CDpkVv68.js";const h=JSON.parse('{"title":"Estadísticas","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/characters/stats.md","filePath":"es/guide/characters/stats.md"}'),r={name:"es/guide/characters/stats.md"};function n(o,a,d,c,l,p){return t(),s("div",null,[...a[0]||(a[0]=[i('<h1 id="stats" tabindex="-1">Estadísticas <a class="header-anchor" href="#stats" aria-label="Enlace permanente a &quot;Estadísticas&quot;">​</a></h1><p><strong>Estado:</strong> Propuesto · Disponibilidad no confirmada.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Enlace permanente a &quot;TL;DR&quot;">​</a></h2><ul><li>STR, DEX e INT siguen siendo las únicas estadísticas principales.</li><li>Las estadísticas apoyan el <a href="/Syrolands-Public/es/guide/glossary.html#handling">manejo</a>, el control y la capacidad mental; una DEX baja no debería hacer que jugar normalmente parezca ir a cámara lenta.</li><li>Athletics es una <a href="/Syrolands-Public/es/guide/characters/skills.html">habilidad</a>/especialización. Max <a href="/Syrolands-Public/es/guide/combat/stamina-and-reactive-combat.html">Stamina</a> no tiene una fórmula definitiva.</li></ul><p><span id="stats-overview"></span><span id="responsiveness-comes-first"></span><span id="what-each-stat-could-contribute"></span><span id="stats-support-expertise"></span><span id="int-and-prepared-magic"></span><span id="stamina-capacity-is-still-open"></span></p><h2 id="how-it-works" tabindex="-1">Cómo funciona <a class="header-anchor" href="#how-it-works" aria-label="Enlace permanente a &quot;Cómo funciona&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Elemento</th><th>Qué significa para el jugador</th></tr></thead><tbody><tr><td>STR</td><td>Puede ayudar con equipo pesado, carga y acciones físicas exigentes; no es simplemente un multiplicador universal de daño.</td></tr><tr><td>DEX</td><td>Puede apoyar la recuperación dentro de límites, el equilibrio y el control bajo presión.</td></tr><tr><td>INT</td><td>Puede apoyar <a href="/Syrolands-Public/es/guide/magic/memory-and-familiarity.html">Active Memory</a> y patrones mágicos complejos; sus relaciones con los recursos siguen abiertas.</td></tr></tbody></table><h2 id="compared-with-classic-uo" tabindex="-1">Comparado con UO clásico <a class="header-anchor" href="#compared-with-classic-uo" aria-label="Enlace permanente a &quot;Comparado con UO clásico&quot;">​</a></h2><table tabindex="0"><thead><tr><th>UO clásico</th><th>Orientación de Syrolands</th></tr></thead><tbody><tr><td>STR, DEX e INT contribuyen a los atributos del personaje.</td><td>Se conservan estas tres estadísticas, reconsiderando su papel en el manejo y la capacidad de respuesta.</td></tr><tr><td>Las estadísticas interactúan con las habilidades al crear un personaje.</td><td>La pericia con armas y el conocimiento mágico siguen siendo distintos de las estadísticas básicas.</td></tr></tbody></table><p>Las reglas de UO varían según la época y el shard. <a href="https://uo.com/wiki/ultima-online-wiki/player/stats/skills-stats-and-attributes/" target="_blank" rel="noreferrer">UO oficial: habilidades, estadísticas y atributos</a>.</p><h2 id="example" tabindex="-1">Ejemplo <a class="header-anchor" href="#example" aria-label="Enlace permanente a &quot;Ejemplo&quot;">​</a></h2><p>La fuerza podría ayudarte a manejar un martillo pesado, pero conocer sus <a href="/Syrolands-Public/es/guide/characters/techniques.html">técnicas</a> y elegir el momento oportuno debería seguir distinguiendo a un combatiente capaz.</p><h2 id="progression-trade-offs" tabindex="-1">Progresión y contrapartidas <a class="header-anchor" href="#progression-trade-offs" aria-label="Enlace permanente a &quot;Progresión y contrapartidas&quot;">​</a></h2><p>Athletics puede apoyar la eficiencia de stamina, la recuperación y el esfuerzo sostenido. Una Endurance/Stamina Capacity derivada es solo una hipótesis; no hay una nueva estadística CON ni una fórmula definitiva de capacidad. STR no debería ser la única estadística de stamina, e INT no debería exigir inversión solo para preparar <a href="/Syrolands-Public/es/guide/combat/special-attacks.html">SAs</a> marciales.</p><h2 id="related" tabindex="-1">Relacionado <a class="header-anchor" href="#related" aria-label="Enlace permanente a &quot;Relacionado&quot;">​</a></h2><p><a href="/Syrolands-Public/es/guide/characters/skills.html">Habilidades</a> · <a href="/Syrolands-Public/es/guide/magic/memory-and-familiarity.html">Memoria de hechizos</a> · <a href="/Syrolands-Public/es/guide/combat/overview.html">Combate</a></p><h2 id="full-design-specification" tabindex="-1">Especificación de diseño completa <a class="header-anchor" href="#full-design-specification" aria-label="Enlace permanente a &quot;Especificación de diseño completa&quot;">​</a></h2><p>Consulta la especificación de diseño: <a href="/Syrolands-Public/es/game-design/characters/stats.html">Estadísticas</a>.</p>',18)])])}const m=e(r,[["render",n]]);export{h as __pageData,m as default};
